const $=s=>document.querySelector(s);
const isNat=()=>{try{return !!(window.Capacitor&&Capacitor.isNativePlatform&&Capacitor.isNativePlatform())}catch(e){return false}};
const b64=b=>new Promise((ok,no)=>{const r=new FileReader();r.onload=()=>ok(String(r.result).split(',')[1]);r.onerror=no;r.readAsDataURL(b)});
async function saveFile(blob,fn,text){
if(isNat()){try{const P=Capacitor.Plugins||{};if(!P.Filesystem||!P.Share)throw new Error('plugin');const r=await P.Filesystem.writeFile({path:fn,data:await b64(blob),directory:'CACHE'});await P.Share.share({title:fn,text:text||'',files:[r.uri],dialogTitle:'Save / Share'});return true}catch(e){if(/cancel/i.test(String((e&&e.message)||e)))return true}}
try{const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=fn;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),60000)}catch(e){}return false}
function openExt(u){if(isNat()){const A=Capacitor.Plugins&&Capacitor.Plugins.App;if(A&&A.openUrl){A.openUrl({url:u}).catch(()=>{location.href=u});return}location.href=u;return}window.open(u,'_blank')}
let D=[];try{D=JSON.parse(localStorage.getItem('wk')||'[]')}catch(e){}
if(!Array.isArray(D))D=[];
const nk=s=>String(s||'').toUpperCase().replace(/[^A-Z0-9]/g,'');
const fixD=()=>{D=D.filter(j=>j&&typeof j==='object');D.forEach(j=>{if(!Array.isArray(j.items))j.items=[];if(!Array.isArray(j.payments))j.payments=[];j.bike=j.bike||'';j.name=j.name||'';if(!j.date)j.date=today()})};
const store=()=>{try{localStorage.setItem('wk',JSON.stringify(D));localStorage.setItem('wk_ts',String(Date.now()))}catch(e){if(!window._qa){window._qa=1;alert('Browser ki memory bhar gayi. Data doosri copy me safe hai, abhi Backup file download kar lo.')}}mir()};
const SHOP='Shree Kasthbhanjan';
const DEF=['Engine oil','Oil filter','Air filter','Spark plug','Chain lube / set','Brake pads','Clutch / accelerator wire','Labour (service)','Washing'];
let view='jobs',cur=null,q='';
const R=n=>'₹'+(Math.round(+n)||0);
const today=()=>{const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')};
const days=d=>{const a=new Date(today()+'T00:00:00'),b=new Date(String(d||'').slice(0,10)+'T00:00:00'),x=Math.round((a-b)/864e5);return isNaN(x)?0:x};
const esc=s=>String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tot=j=>(j.items||[]).reduce((s,i)=>s+(i.on?+i.c||0:0),0);
const bal=j=>tot(j)-(+j.paid||0);
function wa(ph,msg){let p=(ph||'').replace(/\D/g,'');if(p.length==11&&p[0]=='0')p=p.slice(1);if(p.length==10)p='91'+p;if(p.length<10){alert('Sahi mobile number daalo');return}openExt('https://wa.me/'+p+'?text='+encodeURIComponent(msg))}
function bill(j){const L=j.items.filter(i=>i.on&&+i.c).map(i=>'• '+i.n+': '+R(i.c));
return '*'+SHOP+'*\nNamaste '+j.name+',\nBike: '+j.bike+(j.model?' ('+j.model+')':'')+'\nKM: '+(j.km||'-')+'\nDate: '+j.date+'\n\n'+(j.complaint?'Complaint: '+j.complaint+'\n':'')+(j.notes?'Work done: '+j.notes+'\n\n':'\n')+L.join('\n')+'\n\n*Total: '+R(tot(j))+'*\nPaid: '+R(j.paid)+'\n*Baaki: '+R(bal(j))+'*\n'+(j.nextKm?'Next service: '+j.nextKm+' KM\n':'')+'\nDhanyavaad! Agli service yaad rakhiye.'}
const remMsg=(j,d)=>'Namaste '+j.name+', '+SHOP+' se message. Aapki bike '+j.bike+' ki last service ko '+d+' din ho gaye hain. Service ka time ho gaya hai.'+(j.nextKm?' Next service target: '+j.nextKm+' KM.':'')+' Kripya bike le aaiye. Dhanyavaad!';
const dueMsg=j=>'Namaste '+j.name+', '+SHOP+' se message. Aapki bike '+j.bike+' ka '+R(bal(j))+' baaki hai. Kripya jald pay kar dein. Dhanyavaad!';
function newJob(){return{id:Date.now(),date:today(),name:'',phone:'',bike:'',model:'',km:'',complaint:'',notes:'',nextKm:'',items:DEF.map(n=>({n,c:'',on:false})),paid:'',payments:[],payMode:'Cash',done:false}}
let autoV={name:'',phone:'',model:''},autoIt=null,nmOpts=[];
function prevOf(k){return[...D].reverse().filter(x=>nk(x.bike)===k)}
function lookup(){if(!cur)return;const k=nk(cur.bike);if(k.length<3){bikeHint();return}const p=prevOf(k).find(x=>x.id!==cur.id)||null;
['name','phone','model'].forEach(f=>{if(!cur[f]||cur[f]===autoV[f]){const v=p?(p[f]||''):'';cur[f]=v;autoV[f]=v;}});
const ids={name:'fn',phone:'fp',model:'fm'};Object.keys(ids).forEach(f=>{const e=document.getElementById(ids[f]);if(e&&e.value!==(cur[f]||''))e.value=cur[f]||''});
const isNew=!D.some(x=>x.id==cur.id);
if(p&&isNew&&!cur.items.some(i=>i.on)&&(cur.items===autoIt||cur.items.every(i=>i.c===''))){cur.items=p.items.map(i=>({n:i.n,c:i.c,on:false}));autoIt=cur.items;const l=document.getElementById('itl');if(l){l.innerHTML=itemsHtml();const sr=document.getElementById('isr');if(sr)itemSearch(sr.value);upd(1)}}
bikeHint()}
function bikeHint(){const el=document.getElementById('bnh');if(!el||!cur)return;const k=nk(cur.bike);nmOpts=[];
if(k.length>=3){const seen=new Set();prevOf(k).forEach(x=>{const n=String(x.name||'').trim();if(!n||seen.has(n.toLowerCase()))return;seen.add(n.toLowerCase());nmOpts.push({n,p:x.phone||'',m:x.model||''})})}
if(!nmOpts.length){el.innerHTML='';return}
el.innerHTML='<div class="mini" style="margin-top:6px">Is bike ke pehle ke naam (tap karke chuno):</div><div class="row" style="flex-wrap:wrap;margin-top:4px">'+nmOpts.map((o,i)=>'<button type="button" class="btn g s" onclick="pickName('+i+')">'+esc(o.n)+'</button>').join('')+'<button type="button" class="btn s" onclick="addName()">+ Dusra naam jodo</button></div>'}
function pickName(i){const o=nmOpts[i];if(!o||!cur)return;cur.name=o.n;if(o.p)cur.phone=o.p;if(o.m&&!cur.model)cur.model=o.m;
[['fn','name'],['fp','phone'],['fm','model']].forEach(([id,f])=>{const e=document.getElementById(id);if(e)e.value=cur[f]||''})}
function addName(){const e=document.getElementById('fn');if(!e||!cur)return;let v=String(cur.name||'').trim();if(v&&!/\/\s*$/.test(v))v+=' / ';cur.name=v;e.value=v;e.focus();try{e.setSelectionRange(v.length,v.length)}catch(x){}}
const lastDone=()=>{const m={};D.filter(j=>j.done).forEach(j=>{const k=nk(j.bike)||j.bike,o=m[k];if(!o||String(j.date)>=String(o.date))m[k]=j});return Object.values(m)};
function go(v){view=v;cur=null;render()}
function render(){if(licLocked()){$('#nav').innerHTML='';$('#app').innerHTML=lockScr();return}render0()}
function render0(){navTrack();
const nav=[['jobs','Job cards','<path d="M9 3h6l1 2h3v16H5V5h3zM8 11h8M8 15h8"/>'],['remind','Reminders','<path d="M6 17V11a6 6 0 0112 0v6l2 2H4zM10 21h4"/>'],['pend','Pending','<path d="M7 5h10M7 9h10M10 5c5 0 5 7 0 7H7l8 8"/>'],['more','More','<path d="M4 7h16M4 12h16M4 17h16"/>']];
$('#nav').innerHTML=nav.map(n=>`<button class="${view==n[0]||(n[0]=='remind'&&view=='rcf')||(n[0]=='more'&&!'jobs remind pend rcf'.includes(view))?'on':''}" onclick="go('${n[0]}')"><svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">${n[2]}</svg>${n[1]}</button>`).join('');
$('#app').innerHTML=cur?form():({jobs:list,remind:rem,pend,more,stock,exp,rep,bk,trash,hist,fold,lic,rcf:rcForm})[view]()}
function jobCards(){const t=q.trim().toLowerCase(),tk=nk(q);const A=[...D].reverse().filter(j=>!t||((j.bike||'')+' '+(j.name||'')+' '+(j.phone||'')).toLowerCase().includes(t)||(tk&&nk(j.bike).includes(tk))),L=A.slice(0,lim);
return (L.length?L.map(j=>`<div class="card"><div class="top"><div><span class="plate">${esc(j.bike)}</span> <span class="pill ${j.done?'k':'o'}">${j.done?'Done':'Open'}</span><br>${esc(j.name)} <span class="mut">${esc(j.model)}</span><br><span class="mini">KM ${esc(j.km||'-')}${j.complaint?' · '+esc(j.complaint.slice(0,55)):''}</span></div><div style="text-align:right"><b>${R(tot(j))}</b><br><span class="mut">${j.date}</span></div></div>
${bal(j)>0?`<div class="mut" style="color:var(--warn)">Baaki: ${R(bal(j))}</div>`:''}
<div class="row" style="margin-top:8px;flex-wrap:wrap"><button class="btn g s" onclick="edit(${j.id})">Edit</button><button class="btn g s" onclick="hb=D.find(x=>x.id==${j.id}).bike;go('hist')">History</button><button class="btn g s" onclick="prt(${j.id})">Print</button><button class="btn wa s" onclick="sendBill(${j.id})">WhatsApp</button><button class="btn g s" onclick="shareBill(${j.id})">PDF share</button><button class="btn d s" onclick="del(${j.id})">Delete</button></div></div>`).join(''):'<p class="mut">Abhi koi job card nahi hai. Upar se naya banao.</p>')+(A.length>lim?`<button class="btn g" style="width:100%" onclick="lim+=100;render()">Aur dikhao (${A.length-lim} baaki)</button>`:'')}
function list(){
return stats()+licBn()+fb()+bnr()+`<button class="btn" style="width:100%;margin-bottom:10px" onclick="cur=newJob();render()">+ New job card</button>
<input placeholder="Bike number / naam / mobile search" value="${esc(q)}" oninput="q=this.value;lim=100;$('#jl').innerHTML=jobCards()" style="margin-bottom:10px"><div id="jl">${jobCards()}</div>`}
function rem(){const L=lastDone().map(j=>({j,d:days(j.date),sent:!!j.remAt,kmDue:j.nextKm&&j.km&&+j.km>=+j.nextKm})).sort((a,b)=>(a.sent-b.sent)||(b.d-a.d));
return `<h3 style="margin:4px 0 10px">60 din service reminder</h3>`+rcBar()+(L.length?L.map(({j,d,sent,kmDue})=>`<div class="card"><div class="top"><div><span class="plate">${esc(j.bike)}</span> ${esc(j.name)}<br><span class="mut">Last service: ${j.date} · KM ${esc(j.km||'-')}</span></div><span class="pill ${sent?'':d>=60?'r':d>=50?'o':''}">${d} din${sent?' · reminder bheja '+j.remAt:(d>=60?' - due':'')+(kmDue?' · KM due':'')}</span></div>
<div class="row" style="margin-top:8px"><button class="btn wa s" onclick="sendRem(${j.id},${d})">${sent?'Dobara bhejo':'WhatsApp reminder'}</button></div></div>`).join(''):'<p class="mut">Jab job "work done" mark hoga, bike yahan aa jayegi.</p>')+rcCards()}
function pend(){const L=D.filter(j=>bal(j)>0).reverse();const S=L.reduce((s,j)=>s+bal(j),0);
return `<div class="big"><div class="card"><div class="mut">Total baaki</div><div class="tot" style="color:var(--warn)">${R(S)}</div></div><div class="card"><div class="mut">Customers</div><div class="tot">${L.length}</div></div></div><div style="height:10px"></div>`+
(L.length?L.map(j=>`<div class="card"><div class="top"><div><span class="plate">${esc(j.bike)}</span> ${esc(j.name)}<br><span class="mut">${j.date} | Total ${R(tot(j))} | Mila ${R(j.paid)}</span></div><b style="color:var(--warn)">${R(bal(j))}</b></div>
<div class="row" style="margin-top:8px"><button class="btn s" onclick="recv(${j.id})">Paisa mila</button><button class="btn wa s" onclick="wa(D.find(x=>x.id==${j.id}).phone,dueMsg(D.find(x=>x.id==${j.id})))">WhatsApp</button></div></div>`).join(''):'<p class="mut">Koi pending amount nahi.</p>')}
function form(){const j=cur;return `<div class="card"><b>${D.some(x=>x.id==j.id)?'Edit job card':'New job card'}</b>
<label>Bike number</label><input class="pin" value="${esc(j.bike)}" placeholder="GJ 01 AB 1234" style="text-transform:uppercase" oninput="cur.bike=this.value.toUpperCase();bikeHint()" onchange="lookup()"><div id="bnh"></div>
<label>Customer naam</label><input id="fn" value="${esc(j.name)}" oninput="cur.name=this.value">
<label>Mobile (WhatsApp)</label><input id="fp" type="tel" inputmode="numeric" value="${esc(j.phone)}" oninput="cur.phone=this.value">
<div class="row"><div><label>Bike model</label><input id="fm" value="${esc(j.model)}" oninput="cur.model=this.value"></div><div><label>KM</label><input type="number" value="${esc(j.km)}" oninput="cur.km=this.value"></div></div>
<label>Customer ki complaint / problem</label><textarea class="note" placeholder="Customer ne kya problem batayi..." oninput="cur.complaint=this.value">${esc(j.complaint)}</textarea>
<label>Mechanic finding / work notes</label><textarea class="note" placeholder="Kya check kiya, kya repair/replacement hua..." oninput="cur.notes=this.value">${esc(j.notes)}</textarea>
<div class="row"><div><label>Date</label><input type="date" value="${j.date}" onchange="cur.date=this.value"></div><div><label>Next service KM</label><input type="number" value="${esc(j.nextKm)}" placeholder="e.g. 15000" oninput="cur.nextKm=this.value"></div></div></div>
<div class="card"><b>Service / parts</b><div class="mut">Tick karo, charge khud edit karo</div>
<input id="isr" type="search" placeholder="Item search karo (jaise oil, filter)" style="margin-top:8px" oninput="itemSearch(this.value)"><div id="isn" class="mut" style="display:none;margin-top:6px">Koi item nahi mila. Neeche "Aur item" me naya add kar sakte ho.</div>
<div id="itl">${itemsHtml()}</div>
<div class="row" style="margin-top:10px"><input id="xn" placeholder="Aur item (naam)"><input id="xc" type="number" placeholder="₹" style="max-width:90px;flex:none"><button class="btn s" onclick="addItem()">Add</button></div></div>
<div class="card sum"><div class="top"><span>Total</span><span class="tot" id="T">${R(tot(j))}</span></div>
<label>Paid (mila hua)</label><input type="number" inputmode="decimal" value="${j.paid}" oninput="cur.paid=this.value;upd(1)">
<label>Payment mode</label><select onchange="cur.payMode=this.value"><option ${j.payMode==='Cash'?'selected':''}>Cash</option><option ${j.payMode==='UPI'?'selected':''}>UPI</option><option ${j.payMode==='Card'?'selected':''}>Card</option><option ${j.payMode==='Bank'?'selected':''}>Bank</option></select>
<div class="top" style="margin-top:8px"><span>Baaki</span><b id="B" style="color:var(--warn)">${R(bal(j))}</b></div>
${(j.payments&&j.payments.length)?`<div class="mini" style="margin-top:10px"><b>Payment history</b>${j.payments.slice().reverse().map(p=>`<div>${esc(p.date)} · ${R(p.amount)} · ${esc(p.mode)}</div>`).join('')}</div>`:''}</div>
<div class="row"><button class="btn g" onclick="cur=null;render()">Cancel</button><button class="btn" onclick="saveJob(0)">Save</button></div>
<button class="btn wa" style="width:100%;margin-top:8px" onclick="saveJob(1)">Kaam hua: Save + WhatsApp bill</button>`}

function itemsHtml(){const j=cur;return j.items.map((i,k)=>`<div class="item" data-n="${esc(i.n).toLowerCase()}"><input type="checkbox" ${i.on?'checked':''} onchange="cur.items[${k}].on=this.checked;upd(1)"><span>${esc(i.n)}</span><input type="number" inputmode="decimal" placeholder="₹" value="${i.c}" oninput="cur.items[${k}].c=this.value;cur.items[${k}].on=true;this.parentNode.querySelector(\'input[type=checkbox]\').checked=true;upd(1)"></div>`).join('')}
function upd(soft){$('#T').textContent=R(tot(cur));$('#B').textContent=R(bal(cur));if(!soft)render()}
function itemSearch(v){v=(v||'').trim().toLowerCase();let c=0;document.querySelectorAll('.item[data-n]').forEach(e=>{const m=!v||e.dataset.n.includes(v);e.style.display=m?'':'none';if(m)c++});const n=document.getElementById('isn');if(n)n.style.display=(v&&!c)?'block':'none'}
function addItem(){const n=$('#xn').value.trim();if(!n)return;cur.items.push({n,c:$('#xc').value,on:true});render()}
function saveJob(done){const j=cur;if(!j.bike.trim()||!j.name.trim()){alert('Bike number aur customer naam zaruri hai');return}
const old=D.find(x=>x.id==j.id);const oldPaid=old?(+old.paid||0):0;const newPaid=+j.paid||0;
j.bike=j.bike.trim().replace(/\s+/g,' ').toUpperCase();j.name=j.name.trim();if(done)j.done=true;j.payments=j.payments||[];
if(newPaid>oldPaid){j.payments.push({date:today(),amount:newPaid-oldPaid,mode:j.payMode||'Cash'});}
if(done&&!j.stk){j.items.filter(i=>i.on).forEach(i=>{const s=S.find(x=>x.n.toLowerCase()==i.n.toLowerCase());if(s)s.q--});j.stk=1;sv('wk_s',S)}
const k=D.findIndex(x=>x.id==j.id);k<0?D.push(j):D[k]=j;store();cur=null;render();if(done)billSend(j)}
function edit(id){cur=JSON.parse(JSON.stringify(D.find(x=>x.id==id)));render()}
function sendBill(id){const j=D.find(x=>x.id==id);billSend(j)}
function sendRem(id,d){const j=D.find(x=>x.id==id);wa(j.phone,remMsg(j,d));j.remAt=today();store();render()}
function del(id){const j=D.find(x=>x.id==id);if(!j)return;if(confirm('Job card Trash me bhejna hai? Data permanently delete nahi hoga.')){TR.push({...j,deletedAt:today()});D=D.filter(x=>x.id!=id);store();sv('wk_trash',TR);render()}}
function recv(id){const j=D.find(x=>x.id==id);const a=parseFloat(prompt('Kitna paisa mila? (baaki '+R(bal(j))+')'));if(a>0){const mode=prompt('Payment mode: Cash / UPI / Card / Bank','Cash')||'Cash';j.paid=(+j.paid||0)+a;j.payments=j.payments||[];j.payments.push({date:today(),amount:a,mode:mode});j.payMode=mode;store();render()}}

const ld=(k,d)=>{try{return JSON.parse(localStorage.getItem(k))||d}catch(e){return d}};
const sv=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v));localStorage.setItem('wk_ts',String(Date.now()))}catch(e){}mir()};
fixD();let S=ld('wk_s',[]),E=ld('wk_e',[]),TR=ld('wk_trash',[]),RC=ld('wk_rc',[]),ad=today(),rm=today().slice(0,7),hb='';
const back=t=>`<div class="row" style="margin-bottom:10px"><button class="btn g s" onclick="go('more')">← Back</button><b style="flex:3">${t}</b></div>`;
function more(){return [['fold','Excel / Folder save'],['stock','Parts stock'],['exp','Kharcha'],['rep','Report'],['bk','Backup / restore'],['trash','Trash / restore'],['lic','License / Subscription']].map(b=>`<button class="btn g" style="width:100%;margin-bottom:8px;text-align:left" onclick="go('${b[0]}')">${b[1]}</button>`).join('')}
function stock(){return back('Parts stock')+S.map(s=>`<div class="card"><div class="top"><b>${esc(s.n)}</b><b style="color:${s.q<=s.min?'var(--warn)':'inherit'}">${s.q}${s.q<=s.min?' (kam)':''}</b></div><div class="row" style="margin-top:8px"><button class="btn s" onclick="rcv(${s.id})">+ Stock aaya</button><button class="btn d s" onclick="delS(${s.id})">Delete</button></div></div>`).join('')+`<div class="card"><input id="sn" placeholder="Part ka naam"><div class="row"><input id="sq" type="number" placeholder="Qty"><input id="sm" type="number" placeholder="Kam hone ki limit"></div><button class="btn" style="width:100%;margin-top:8px" onclick="addS()">Add part</button></div><p class="mut">Part ka naam job card ke item jaisa rakho (jaise Oil filter). Kaam hua par stock khud 1 kam hoga.</p>`}
function addS(){const n=$('#sn').value.trim();if(!n)return;S.push({id:Date.now(),n,q:+$('#sq').value||0,min:+$('#sm').value||0});sv('wk_s',S);render()}
function rcv(id){const a=parseFloat(prompt('Kitna stock aaya?'));if(a>0){S.find(x=>x.id==id).q+=a;sv('wk_s',S);render()}}
function exp(){return back('Kharcha')+`<div class="card"><input type="date" id="ed" value="${today()}"><label>Kis cheez ka</label><input id="en"><label>Amount</label><input id="ea" type="number"><button class="btn" style="width:100%;margin-top:8px" onclick="addE()">Save kharcha</button></div>`+[...E].reverse().map(e=>`<div class="card top"><div>${esc(e.n)}<br><span class="mut">${e.d}</span></div><div><b>${R(e.a)}</b> <button class="btn d s" onclick="delE(${e.id})">X</button></div></div>`).join('')}
function addE(){const n=$('#en').value.trim(),a=+$('#ea').value;if(!n||!a)return;E.push({id:Date.now(),d:$('#ed').value||today(),n,a});sv('wk_e',E);render()}
function rep(){const inM=d=>d.startsWith(rm),J=D.filter(j=>inM(j.date)),rec=a=>a.reduce((s,j)=>s+(+j.paid||0),0),ex=E.filter(e=>inM(e.d)).reduce((s,e)=>s+e.a,0);
return back('Report')+`<div class="card"><div class="mut">Aaj ki kamai (mila)</div><div class="tot">${R(rec(D.filter(j=>j.date==today())))}</div></div><input type="month" value="${rm}" onchange="rm=this.value;render()" style="margin-bottom:10px"><div class="card"><div class="top"><span>Jobs</span><b>${J.length}</b></div><div class="top"><span>Bill total</span><b>${R(J.reduce((s,j)=>s+tot(j),0))}</b></div><div class="top"><span>Paisa mila</span><b>${R(rec(J))}</b></div><div class="top"><span>Kharcha</span><b>${R(ex)}</b></div><div class="top"><span>Munafa (mila - kharcha)</span><b style="color:var(--ac)">${R(rec(J)-ex)}</b></div></div>`}
