const LIC={secret:'SK-71ADFBDB39754007',trialDays:30,seller:'Ram',sellerPhone:'',price:''};
function h53(str,seed){let h1=0xdeadbeef^seed,h2=0x41c6ce57^seed;for(let i=0;i<str.length;i++){const c=str.charCodeAt(i);h1=Math.imul(h1^c,2654435761);h2=Math.imul(h2^c,1597334677)}h1=Math.imul(h1^(h1>>>16),2246822507)^Math.imul(h2^(h2>>>13),3266489909);h2=Math.imul(h2^(h2>>>16),2246822507)^Math.imul(h1^(h1>>>13),3266489909);return 4294967296*(2097151&h2)+(h1>>>0)}
const licSig=d=>h53('SK|'+d+'|'+LIC.secret,7).toString(36).toUpperCase().padStart(8,'0').slice(-8);
function licParse(k){const m=/^SK-(\d{8})-([A-Z0-9]{8})$/.exec(String(k||'').trim().toUpperCase());if(!m||licSig(m[1])!==m[2])return null;const d=m[1].slice(0,4)+'-'+m[1].slice(4,6)+'-'+m[1].slice(6);return isNaN(new Date(d))?null:d}
function licNow(){let t=today();try{const mx=localStorage.getItem('wk_maxd')||'';if(mx>t)t=mx;else localStorage.setItem('wk_maxd',t)}catch(e){}return t}
function licInfo(){const t=licNow();let first=null;try{first=localStorage.getItem('wk_first');if(!first){first=t;localStorage.setItem('wk_first',t)}}catch(e){first=t}
let exp=null;try{exp=licParse(localStorage.getItem('wk_lic'))}catch(e){}
if(exp){const left=Math.round((new Date(exp)-new Date(t))/864e5);return{type:'paid',exp,left,ok:left>=0}}
const end=new Date(new Date(first).getTime()+LIC.trialDays*864e5).toISOString().slice(0,10),left=Math.round((new Date(end)-new Date(t))/864e5);
return{type:'trial',exp:end,left,ok:left>=0}}
const licLocked=()=>!licInfo().ok;
function licSet(){const v=($('#lk').value||'').trim(),e=licParse(v);if(!e){alert('License key galat hai. Dobara dekho.');return}if(e<licNow()){alert('Ye key purani hai (expire ho chuki). Nayi key maango.');return}try{localStorage.setItem('wk_lic',v.toUpperCase())}catch(x){}alert('License chalu ho gaya. Valid till '+e);go('jobs')}
function licAsk(){wa(LIC.sellerPhone,'Namaste, Shree Kasthbhanjan Job Card app ka license chahiye.')}
const licAskBtn=()=>LIC.sellerPhone?`<button class="btn g" style="width:100%;margin-top:8px" onclick="licAsk()">WhatsApp se license maango</button>`:'';
function lockScr(){const i=licInfo();return `<div class="card"><b style="font-size:18px">${i.type=='paid'?'License khatam ho gaya':'Free trial khatam ho gaya'}</b><div class="mut" style="margin:6px 0 10px">Aapka saara data safe hai, kuch delete nahi hua. App chalu karne ke liye license key daalo.${LIC.price?'<br>'+esc(LIC.price):''}</div><label>License key</label><input id="lk" placeholder="SK-YYYYMMDD-XXXXXXXX" autocapitalize="characters"><button class="btn" style="width:100%;margin-top:8px" onclick="licSet()">Chalu karo</button>${licAskBtn()}</div><div class="card"><b>Apna data lo (hamesha free)</b><div class="mut" style="margin:6px 0 10px">License ho ya na ho, data aap download kar sakte ho.</div><button class="btn g" style="width:100%;margin-bottom:8px" onclick="expD()">Backup file download karo</button><button class="btn g" style="width:100%" onclick="dlXlsx()">Excel file download karo</button></div>`}
function lic(){const i=licInfo();return back('License')+`<div class="card"><b>${i.type=='paid'?'License chalu hai':'Free trial chal raha hai'}</b><div class="mut" style="margin-top:6px">Valid till: ${i.exp} · ${i.left} din baaki</div></div><div class="card"><label>Nayi license key</label><input id="lk" placeholder="SK-YYYYMMDD-XXXXXXXX" autocapitalize="characters"><button class="btn" style="width:100%;margin-top:8px" onclick="licSet()">Key lagao</button>${licAskBtn()}</div>`}
function licBn(){const i=licInfo();return i.left<=7?`<div class="card" style="border-color:var(--warn)"><b>${i.type=='paid'?'License':'Free trial'} ${i.left} din me khatam hoga</b><div class="mut" style="margin:6px 0">Data kuch nahi hatega. Chalu rakhne ke liye renew karo.</div><button class="btn s" onclick="go('lic')">Renew / key lagao</button></div>`:''}
