var rcCur=null;
const newRC=()=>({id:Date.now(),name:'',phone:'',bike:'',date:today(),km:'',note:'',remAt:''});
const rcBar=()=>`<button class="btn g" style="width:100%;margin-bottom:10px" onclick="rcOpen()">+ Alag se customer jodo</button>`;
function rcOpen(id){rcCur=id?JSON.parse(JSON.stringify(RC.find(x=>x.id==id))):newRC();go('rcf')}
function rcForm(){if(!rcCur)rcCur=newRC();const c=rcCur;
return `<div class="row" style="margin-bottom:10px"><button class="btn g s" onclick="go('remind')">← Back</button><b style="flex:3">${RC.some(x=>x.id==c.id)?'Customer edit':'Reminder ke liye customer jodo'}</b></div>
<div class="card"><label>Customer naam</label><input value="${esc(c.name)}" oninput="rcCur.name=this.value">
<label>Mobile (WhatsApp)</label><input type="tel" inputmode="numeric" value="${esc(c.phone)}" oninput="rcCur.phone=this.value">
<label>Bike number (ho to)</label><input value="${esc(c.bike)}" style="text-transform:uppercase" oninput="rcCur.bike=this.value.toUpperCase()">
<div class="row"><div><label>Last service date</label><input type="date" value="${esc(c.date)}" onchange="rcCur.date=this.value"></div><div><label>KM (ho to)</label><input type="number" value="${esc(c.km)}" oninput="rcCur.km=this.value"></div></div>
<label>Note (ho to)</label><textarea class="note" oninput="rcCur.note=this.value">${esc(c.note)}</textarea></div>
<div class="row"><button class="btn g" onclick="go('remind')">Cancel</button><button class="btn" onclick="rcSave()">Save</button></div>`}
function rcSave(){const c=rcCur;if(!c.name.trim()||String(c.phone).replace(/\D/g,'').length<10){alert('Naam aur sahi mobile number zaruri hai');return}
c.name=c.name.trim();if(!c.date)c.date=today();const k=RC.findIndex(x=>x.id==c.id);k<0?RC.push(c):RC[k]=c;sv('wk_rc',RC);rcCur=null;go('remind')}
const rcMsg=(c,d)=>'Namaste '+c.name+', '+SHOP+' se message. '+(d>=50?'Aapki bike'+(c.bike?' '+c.bike:'')+' ki last service ko '+d+' din ho gaye hain. Service ka time ho gaya hai.':'Aapki bike'+(c.bike?' '+c.bike:'')+' ki agli service ka reminder.')+' Kripya bike le aaiye. Dhanyavaad!';
function rcSend(id){const c=RC.find(x=>x.id==id);if(!c)return;wa(c.phone,rcMsg(c,days(c.date)));c.remAt=today();sv('wk_rc',RC);render()}
function rcDel(id){const c=RC.find(x=>x.id==id);if(!c||!confirm('Ye customer Trash me jayega, delete nahi hoga. Pakka?'))return;TR.push({kind:'rc',item:c,deletedAt:today()});RC=RC.filter(x=>x.id!=id);sv('wk_rc',RC);sv('wk_trash',TR);render()}
function rcCards(){if(!RC.length)return'';
const L=RC.map(c=>({c,d:days(c.date),sent:!!c.remAt})).sort((a,b)=>(a.sent-b.sent)||(b.d-a.d));
return `<h3 style="margin:16px 0 10px">Alag se jode hue customers</h3>`+L.map(({c,d,sent})=>`<div class="card"><div class="top"><div>${c.bike?`<span class="plate">${esc(c.bike)}</span> `:''}${esc(c.name)}<br><span class="mut">Last service: ${esc(c.date)}${c.km?' · KM '+esc(c.km):''}</span>${c.note?`<div class="mini">${esc(c.note)}</div>`:''}</div><span class="pill ${sent?'':d>=60?'r':d>=50?'o':''}">${d} din${sent?' · reminder bheja '+esc(c.remAt):(d>=60?' - due':'')}</span></div>
<div class="row" style="margin-top:8px;flex-wrap:wrap"><button class="btn wa s" onclick="rcSend(${c.id})">${sent?'Dobara bhejo':'WhatsApp reminder'}</button><button class="btn g s" onclick="rcOpen(${c.id})">Edit</button><button class="btn g s" onclick="rcDel(${c.id})">Trash me bhejo</button></div></div>`).join('')}
/*RC-END*/
