var navKey=null,skipPop=false;
function navTrack(){const k=cur?'form':view;
if(navKey===null){navKey=k;try{history.replaceState({k:k,v:view},'')}catch(e){}return}
if(k===navKey)return;
const wasForm=navKey==='form'||navKey==='rcf';navKey=k;
try{if(wasForm&&k!=='form'&&k!=='rcf'&&history.state&&(history.state.k==='form'||history.state.k==='rcf')){skipPop=true;history.back()}else history.pushState({k:k,v:view},'')}catch(e){}}
window.addEventListener('popstate',e=>{
if(skipPop){skipPop=false;try{history.replaceState({k:navKey,v:view},'')}catch(x){}return}
if(typeof licLocked==='function'&&licLocked())return;
const st=e.state||{};
if(cur){const sv0=D.find(x=>x.id==cur.id);if((cur.bike||cur.name)&&JSON.stringify(cur)!==JSON.stringify(sv0||{})&&!confirm('Job card save nahi hua. Bahar jaoge to ye badlav chale jayenge. Bahar jana hai?')){try{history.pushState({k:'form',v:view},'')}catch(x){}return}cur=null}
view=st.v||'jobs';navKey=view;render()});
