var lim=100;
const kk=x=>x.id!=null?'i'+x.id:(x.kind||'')+JSON.stringify(x.item||x);
function mg(a,b){const k=new Set(a.map(kk));return a.concat(b.filter(x=>!k.has(kk(x))))}
function delS(id){const s=S.find(x=>x.id==id);if(!s||!confirm('Ye part Trash me jayega, delete nahi hoga. Pakka?'))return;TR.push({kind:'stock',item:s,deletedAt:today()});S=S.filter(x=>x.id!=id);sv('wk_s',S);sv('wk_trash',TR);render()}
function delE(id){const e=E.find(x=>x.id==id);if(!e||!confirm('Ye kharcha Trash me jayega, delete nahi hoga. Pakka?'))return;TR.push({kind:'exp',item:e,deletedAt:today()});E=E.filter(x=>x.id!=id);sv('wk_e',E);sv('wk_trash',TR);render()}
function restoreT(i){const t=TR[i];if(!t)return;if(t.kind=='rc')RC.push(t.item);else if(t.kind=='stock')S.push(t.item);else if(t.kind=='exp')E.push(t.item);else{delete t.deletedAt;D.push(t)}TR.splice(i,1);store();sv('wk_s',S);sv('wk_e',E);sv('wk_trash',TR);sv('wk_rc',RC);go(t.kind=='rc'?'remind':t.kind=='stock'?'stock':t.kind=='exp'?'exp':'jobs')}
/*XL-START*/
const XL_FOLDER='Shree Kasthbhanjan Data',XL_FILE='Workshop_Data.xlsx',XL_JSON='Workshop_Backup.json';
const crcT=(()=>{const t=new Uint32Array(256);for(let n=0;n<256;n++){let c=n;for(let k=0;k<8;k++)c=c&1?0xEDB88320^(c>>>1):c>>>1;t[n]=c>>>0}return t})();
const crc32=b=>{let c=0xFFFFFFFF;for(let i=0;i<b.length;i++)c=crcT[(c^b[i])&255]^(c>>>8);return(c^0xFFFFFFFF)>>>0};
function zipStore(files){const enc=new TextEncoder(),parts=[],cen=[];let off=0;
const now=new Date(),dt=((now.getFullYear()-1980)<<9)|((now.getMonth()+1)<<5)|now.getDate(),tm=(now.getHours()<<11)|(now.getMinutes()<<5)|(now.getSeconds()>>1);
files.forEach(f=>{const nm=enc.encode(f.n),crc=crc32(f.d),h=new DataView(new ArrayBuffer(30));
h.setUint32(0,0x04034b50,true);h.setUint16(4,20,true);h.setUint16(6,0x0800,true);h.setUint16(10,tm,true);h.setUint16(12,dt,true);h.setUint32(14,crc,true);h.setUint32(18,f.d.length,true);h.setUint32(22,f.d.length,true);h.setUint16(26,nm.length,true);
parts.push(new Uint8Array(h.buffer),nm,f.d);
const c=new DataView(new ArrayBuffer(46));
c.setUint32(0,0x02014b50,true);c.setUint16(4,20,true);c.setUint16(6,20,true);c.setUint16(8,0x0800,true);c.setUint16(12,tm,true);c.setUint16(14,dt,true);c.setUint32(16,crc,true);c.setUint32(20,f.d.length,true);c.setUint32(24,f.d.length,true);c.setUint16(28,nm.length,true);c.setUint32(42,off,true);
cen.push(new Uint8Array(c.buffer),nm);off+=30+nm.length+f.d.length});
const cs=cen.reduce((s,x)=>s+x.length,0),e=new DataView(new ArrayBuffer(22));
e.setUint32(0,0x06054b50,true);e.setUint16(8,files.length,true);e.setUint16(10,files.length,true);e.setUint32(12,cs,true);e.setUint32(16,off,true);
return new Blob([...parts,...cen,new Uint8Array(e.buffer)],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'})}
const colL=i=>{let s='';i++;while(i>0){const m=(i-1)%26;s=String.fromCharCode(65+m)+s;i=Math.floor((i-1)/26)}return s};
const xe=s=>String(s).replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g,'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
function sheetXml(rows){const W=rows[0].map((_,c)=>Math.min(45,rows.reduce((m,r)=>Math.max(m,String(r[c]==null?'':r[c]).length+2),10)));
let x='<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetViews><sheetView workbookViewId="0"><pane ySplit="1" topLeftCell="A2" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews><cols>'+W.map((w,i)=>`<col min="${i+1}" max="${i+1}" width="${w}" customWidth="1"/>`).join('')+'</cols><sheetData>';
rows.forEach((r,ri)=>{x+=`<row r="${ri+1}">`;r.forEach((v,ci)=>{if(v===''||v==null)return;const ref=colL(ci)+(ri+1),st=ri?'':' s="1"';
if(typeof v==='number'&&isFinite(v))x+=`<c r="${ref}"${st}><v>${v}</v></c>`;else x+=`<c r="${ref}" t="inlineStr"${st}><is><t xml:space="preserve">${xe(v)}</t></is></c>`});x+='</row>'});
return x+'</sheetData></worksheet>'}
function buildXlsx(sh){const enc=new TextEncoder(),H='<?xml version="1.0" encoding="UTF-8" standalone="yes"?>',RS='http://schemas.openxmlformats.org/officeDocument/2006/relationships',PK='http://schemas.openxmlformats.org/package/2006/relationships',SM='http://schemas.openxmlformats.org/spreadsheetml/2006/main';
const F=[
{n:'[Content_Types].xml',x:H+'<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>'+sh.map((_,i)=>`<Override PartName="/xl/worksheets/sheet${i+1}.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>`).join('')+'</Types>'},
{n:'_rels/.rels',x:H+`<Relationships xmlns="${PK}"><Relationship Id="rId1" Type="${RS}/officeDocument" Target="xl/workbook.xml"/></Relationships>`},
{n:'xl/workbook.xml',x:H+`<workbook xmlns="${SM}" xmlns:r="${RS}"><sheets>`+sh.map((s,i)=>`<sheet name="${xe(s.name)}" sheetId="${i+1}" r:id="rId${i+1}"/>`).join('')+'</sheets></workbook>'},
{n:'xl/_rels/workbook.xml.rels',x:H+`<Relationships xmlns="${PK}">`+sh.map((_,i)=>`<Relationship Id="rId${i+1}" Type="${RS}/worksheet" Target="worksheets/sheet${i+1}.xml"/>`).join('')+`<Relationship Id="rId${sh.length+1}" Type="${RS}/styles" Target="styles.xml"/></Relationships>`},
{n:'xl/styles.xml',x:H+`<styleSheet xmlns="${SM}"><fonts count="2"><font><sz val="11"/><name val="Calibri"/></font><font><b/><sz val="11"/><name val="Calibri"/></font></fonts><fills count="2"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill></fills><borders count="1"><border><left/><right/><top/><bottom/><diagonal/></border></borders><cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs><cellXfs count="2"><xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"/><xf numFmtId="0" fontId="1" fillId="0" borderId="0" xfId="0" applyFont="1"/></cellXfs><cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles></styleSheet>`},
...sh.map((s,i)=>({n:`xl/worksheets/sheet${i+1}.xml`,x:sheetXml(s.rows)}))];
return zipStore(F.map(f=>({n:f.n,d:enc.encode(f.x)})))}
function buildSheets(){const n=v=>{const x=parseFloat(String(v==null?'':v).replace(/,/g,''));return isNaN(x)?(v||''):x};
const jc=[['Date','Bike No','Customer','Mobile','Model','KM','Complaint','Work done','Next service KM','Total','Paid','Baaki','Status','Payment mode','Reminder bheja']],
it=[['Date','Bike No','Customer','Item','Amount']],pay=[['Date','Bike No','Customer','Amount','Mode']],
st=[['Part','Qty','Kam hone ki limit','Status']],ex=[['Date','Kharcha ka detail','Amount']],tr=[['Type','Date','Bike No','Customer / Detail','Amount','Deleted on']],ms=[['Month','Jobs','Bill total','Paisa mila','Kharcha','Munafa']],rcs=[['Last service date','Customer','Mobile','Bike No','KM','Note','Reminder bheja']];RC.forEach(c=>rcs.push([c.date,c.name,c.phone||'',c.bike||'',c.km||'',c.note||'',c.remAt||'']));
D.forEach(j=>{jc.push([j.date,j.bike,j.name,j.phone||'',j.model||'',n(j.km),j.complaint||'',j.notes||'',n(j.nextKm),tot(j),+j.paid||0,bal(j),j.done?'Done':'Open',j.payMode||'',j.remAt||'']);
j.items.filter(i=>i.on&&+i.c).forEach(i=>it.push([j.date,j.bike,j.name,i.n,+i.c]));
if(j.payments&&j.payments.length)j.payments.forEach(p=>pay.push([p.date,j.bike,j.name,+p.amount||0,p.mode||'']));else if(+j.paid>0)pay.push([j.date,j.bike,j.name,+j.paid,j.payMode||''])});
S.forEach(s=>st.push([s.n,s.q,s.min,s.q<=s.min?'Kam':'OK']));
[...E].sort((a,b)=>String(a.d).localeCompare(b.d)).forEach(e=>ex.push([e.d,e.n,+e.a||0]));
TR.forEach(j=>tr.push(j.kind=='rc'?['Reminder customer',j.item.date,j.item.bike||'',j.item.name+' ('+(j.item.phone||'')+')','',j.deletedAt||'']:j.kind=='stock'?['Part','','',j.item.n+' (qty '+j.item.q+')','',j.deletedAt||'']:j.kind=='exp'?['Kharcha',j.item.d,'',j.item.n,+j.item.a||0,j.deletedAt||'']:['Job card',j.date,j.bike,j.name,tot(j),j.deletedAt||'']));
const M=[...new Set([...D.map(j=>String(j.date).slice(0,7)),...E.map(e=>String(e.d).slice(0,7))])].sort();
M.forEach(m=>{const J=D.filter(j=>String(j.date).startsWith(m)),k=E.filter(e=>String(e.d).startsWith(m)).reduce((s,e)=>s+(+e.a||0),0),r=J.reduce((s,j)=>s+(+j.paid||0),0);
ms.push([m,J.length,J.reduce((s,j)=>s+tot(j),0),r,k,r-k])});
return[{name:'Job Cards',rows:jc},{name:'Job Items',rows:it},{name:'Payments',rows:pay},{name:'Parts Stock',rows:st},{name:'Kharcha',rows:ex},{name:'Monthly Summary',rows:ms},{name:'Reminder Customers',rows:rcs},{name:'Trash',rows:tr}]}
/*XL-END*/

var dirH=null,fsOk=false,fsMsg='',fsErr='',fsReady=false,fsT=null;
const hasFS=typeof window.showDirectoryPicker==='function';
async function fsPerm(ask){if(!dirH)return false;try{let p=await dirH.queryPermission({mode:'readwrite'});if(p!=='granted'&&ask)p=await dirH.requestPermission({mode:'readwrite'});return fsOk=(p==='granted')}catch(e){return fsOk=false}}
async function fsWrite(name,data){const fh=await dirH.getFileHandle(name,{create:true}),w=await fh.createWritable();await w.write(data);await w.close()}
async function fsSave(ask){if(!hasFS||!dirH)return;
if(!(await fsPerm(ask))){fsMsg='Folder permission chahiye';fsErr='';if(!cur)render();return}
try{await fsWrite(XL_FILE,buildXlsx(buildSheets()));await fsWrite(XL_JSON,JSON.stringify({D,S,E,TR,RC}));fsMsg='Saved: '+new Date().toLocaleString('en-IN');fsErr='';try{localStorage.setItem('wk_lb',JSON.stringify(today()))}catch(e){}}
catch(e){fsErr=(e&&e.name==='NotFoundError')?'Folder hata diya ya move ho gaya. "Folder badlo" dabao.':'Excel file khuli ho to band karo, phir dobara try karo.';fsMsg=fsErr}
if(!cur)render()}
function fsAuto(){if(!dirH||!fsOk)return;clearTimeout(fsT);fsT=setTimeout(()=>fsSave(false),1200)}
async function pickFolder(){try{let h;try{h=await window.showDirectoryPicker({mode:'readwrite',id:'wkfolder',startIn:'documents'})}catch(e){if(e&&e.name==='TypeError')h=await window.showDirectoryPicker({mode:'readwrite'});else throw e}dirH=await h.getDirectoryHandle(XL_FOLDER,{create:true});await idb(x=>x.put(dirH,'dir'));fsOk=true;fsErr='';await fsSave(false)}catch(e){if(!e||e.name!=='AbortError')fsMsg='Ye folder nahi chun paye. Documents ke andar ek naya folder banakar chuno.'}render()}
function dlXlsx(){saveFile(buildXlsx(buildSheets()),'Workshop_Data_'+today()+'.xlsx')}
const fb=()=>{if(!hasFS)return'';
if(dirH&&(!fsOk||fsErr))return `<div class="card" style="border-color:var(--warn)"><b>${fsErr?'Excel save nahi hua':'Excel folder save band hai'}</b><div class="mut">${fsErr?esc(fsErr):'Ek baar allow karo, phir apne aap chalega.'}</div><div class="row" style="margin-top:6px"><button class="btn s" onclick="fsSave(true)">${fsErr?'Dobara try karo':'Folder allow karo'}</button><button class="btn g s" onclick="pickFolder()">Folder badlo</button></div></div>`;
return''};
function fsTap(){if(!dirH)return;document.removeEventListener('click',fsTap,true);if(!fsOk)fsSave(true)}
document.addEventListener('click',fsTap,true);
function fold(){const ok=dirH&&fsOk;
return back('Excel / Folder save')+`<div class="card">`+(!hasFS?`<b>Auto folder save yahan nahi chalega</b><div class="mut" style="margin-top:6px">Ye sirf computer ke Chrome ya Edge me chalta hai. Is device par neeche se Excel file download karo.</div>`
:!dirH?`<b>Folder chuno</b><div class="mut" style="margin:6px 0 10px">Ek baar folder chuno. App uske andar "${XL_FOLDER}" naam ka folder khud bana dega. Uske baad har naya job card, payment, stock ya kharcha save hote hi Excel file apne aap update hogi.</div><button class="btn" style="width:100%" onclick="pickFolder()">Folder chuno</button>`
:`<b>${ok?'Folder connected':'Permission chahiye'}</b><div class="mut" style="margin:6px 0">Folder: ${esc(dirH.name)}<br>Excel file: ${XL_FILE}<br>Backup file: ${XL_JSON}</div><div class="mut" style="color:var(--ac)">${esc(fsMsg)}</div><div class="row" style="margin-top:10px"><button class="btn s" onclick="fsSave(true)">Abhi save karo</button><button class="btn g s" onclick="pickFolder()">Folder badlo</button></div>`)+`</div>
<div class="card"><button class="btn g" style="width:100%" onclick="dlXlsx()">Excel file download karo</button></div>
<div class="card"><b>Excel me ye sheets banti hain</b><div class="mut" style="margin-top:6px">Job Cards, Job Items, Payments, Parts Stock, Kharcha, Monthly Summary, Trash</div></div>`}
if(hasFS)idb(x=>new Promise(ok=>{const g=x.get('dir');g.onsuccess=()=>ok(g.result);g.onerror=()=>ok(null)})).then(async h=>{if(h){dirH=h;await fsPerm(false)}}).catch(()=>{}).then(()=>{fsReady=true;render()});

render();
